<template><AdminLayout title="Stories"><div v-if="message" class="admin-notice">{{message}}</div><div v-if="error" class="admin-error">{{error}}</div><div class="admin-card"><h2>{{editing?'Edit story':'Create a story'}}</h2><form @submit.prevent="save"><div class="field"><label>Title *</label><input v-model="form.title" required></div><div class="field"><label>Excerpt</label><textarea v-model="form.excerpt" rows="2"></textarea></div><div class="field"><label>Body *</label><textarea v-model="form.body" rows="9" required></textarea></div><div class="field"><label>Photo</label><input type="file" accept="image/*" @change="e=>form.image=e.target.files[0]"></div><div class="pill-row"><label><input type="checkbox" v-model="form.is_published"> Publish</label><input v-model="form.published_at" type="datetime-local"></div><br><button class="btn btn-primary" :disabled="saving">{{saving?(editing?'Updating…':'Publishing…'):(editing?'Update':'Publish')}} →</button><button v-if="editing" type="button" class="btn btn-secondary" @click="reset">Cancel</button></form></div><div class="admin-card"><h2>Published & draft stories</h2><table class="table"><thead><tr><th>Title</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody><tr v-for="p in posts" :key="p.id"><td>{{p.title}}</td><td><span class="badge">{{p.is_published?'Published':'Draft'}}</span></td><td>{{format(p.published_at)}}</td><td><button type="button" class="copy-btn" @click="edit(p)">Edit</button> <button type="button" class="copy-btn danger-btn" @click="remove(p)">Delete photo/story</button></td></tr></tbody></table></div></AdminLayout></template>
<script setup>import {ref,onMounted,reactive} from 'vue';import axios from 'axios';import AdminLayout from '../components/AdminLayout.vue';const posts=ref([]),editing=ref(null),saving=ref(false),message=ref(''),error=ref(''),form=reactive({title:'',excerpt:'',body:'',image:null,published_at:'',is_published:false});const load=async()=>{try{posts.value=(await axios.get('/api/admin/posts')).data.data||[]}catch(e){error.value=e.response?.data?.message||'Could not load stories. Please sign in again.'}};const reset=()=>{editing.value=null;Object.assign(form,{title:'',excerpt:'',body:'',image:null,published_at:'',is_published:false})};const edit=p=>{error.value='';message.value='';editing.value=p;Object.assign(form,{title:p.title,excerpt:p.excerpt||'',body:p.body,image:null,published_at:p.published_at?new Date(p.published_at).toISOString().slice(0,16):'',is_published:p.is_published})};const save=async()=>{saving.value=true;error.value='';message.value='';try{const fd=new FormData();Object.entries(form).forEach(([k,v])=>{if(v!==null&&v!==undefined)fd.append(k,k==='is_published'?(v?'1':'0'):v)});if(editing.value){fd.append('_method','PUT');await axios.post('/api/admin/posts/'+editing.value.id,fd);message.value='Story updated.'}else{await axios.post('/api/admin/posts',fd);message.value='Story published.'}reset();await load()}catch(e){error.value=e.response?.data?.message||'Could not save this story.'}finally{saving.value=false}};const remove=async p=>{if(!confirm('Delete this story and its uploaded photo permanently?'))return;error.value='';message.value='';try{await axios.delete('/api/admin/posts/'+p.id);message.value='Story and photo deleted.';await load()}catch(e){error.value=e.response?.data?.message||'Could not delete this story. Please sign in again.'}};const format=d=>d?new Date(d).toLocaleDateString():'';onMounted(load)</script>
